package com.franco.desco.adapter.in.web.employee;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.employee.EmployeeCommands.GetEmployee;import com.franco.desco.application.employee.port.in.EmployeeUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/empleados") @Tag(name="Empleados",description="Administración de empleados y su adscripción organizacional.") @SecurityRequirement(name=OpenApiConstants.BEARER_AUTH) @Validated public class EmployeeController{private final EmployeeUseCase u;private final EmployeeWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public EmployeeController(EmployeeUseCase u,EmployeeWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping @PreAuthorize("@permissionGuard.has(authentication,'EMPLEADOS_LISTAR')") @Operation(operationId="empleadosListar",summary="Listar empleados") public ResponseEntity<ApiResponse<PageResponse<EmployeeResponses.Summary>>>list(@RequestParam(required=false) Long empresaId,@RequestParam(required=false) Long areaId,@RequestParam(required=false) Boolean activo,@RequestParam(defaultValue="1") @Min(1) int pagina,@RequestParam(defaultValue="20") @Min(1) @Max(100) int tamano,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,empresaId,areaId,activo),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}") @PreAuthorize("@permissionGuard.has(authentication,'EMPLEADOS_VER')") @Operation(operationId="empleadosVer",summary="Ver empleado") public ResponseEntity<ApiResponse<EmployeeResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.get(new GetEmployee(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'EMPLEADOS_CREAR')") @Operation(operationId="empleadosCrear",summary="Registrar empleado") public ResponseEntity<ApiResponse<EmployeeResponses.Created>>create(@Valid @RequestBody EmployeeRequests.Create q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.create(map.command(q),ids.resolve(a),meta.resolve(r)),r,EmployeeResponses.Created::new);}
 @PutMapping("/{id}") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'EMPLEADOS_EDITAR')") @Operation(operationId="empleadosEditar",summary="Editar empleado") public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid @RequestBody EmployeeRequests.Update q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.update(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/retirar") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'EMPLEADOS_RETIRAR')") @Operation(operationId="empleadosRetirar",summary="Retirar empleado") public ResponseEntity<ApiResponse<Void>>retire(@PathVariable Long id,@Valid @RequestBody EmployeeRequests.Retire q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.retire(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
}
